function searchToursMemoryPath(): { file: string; line: number; context: string }[] {
  // Use searchText to find all occurrences of '.tours/.memory' in the workspace
  const matches = searchText('.tours/.memory');
  return matches.map(m => ({ file: m.file, line: m.line, context: m.text.trim() }));
}

function listRelevantFiles(): string[] {
  // List files in src/ and related directories to confirm presence of memory-related files
  const files = listFiles();
  const relevant = files.filter(f => 
    f.startsWith('src/') && 
    (f.includes('memory') || f.includes('replay') || f.includes('function_try'))
  );
  return relevant;
}

function findMemoryRunReferences(): { file: string; line: number; context: string }[] {
  // Search for memory_run function calls or definitions
  const matches = searchText('memory_run');
  return matches.map(m => ({ file: m.file, line: m.line, context: m.text.trim() }));
}

function readMemoryTs(): { file: string; lines: string[] } {
  const res = readLines('src/memory.ts', 1, 100);
  return { file: res.file, lines: res.lines };
}

function readSrcMemoryTs(): { file: string; line: number; text: string }[] {
  const matches = searchText('memory.ts');
  // Filter to lines that actually contain content from src/memory.ts
  const relevant = matches.filter(m => m.file === 'src/memory.ts');
  return relevant.map(m => ({ file: m.file, line: m.line, text: m.text.trim() }));
}

function readSrcMemoryTsLines(): { file: string; line: number; text: string }[] {
  // Use searchText to find lines in src/memory.ts
  const matches = searchText('src/memory.ts');
  return matches.map(m => ({ file: m.file, line: m.line, text: m.text.trim() }));
}

function findMemoryTsKeyLines(): { file: string; line: number; text: string }[] {
  // Search for key lines in src/memory.ts related to persistence and matching
  const matches = searchText('src/memory.ts');
  const relevant = matches
    .filter(m => m.file === 'src/memory.ts')
    .filter(m => 
      m.text.includes('export') ||
      m.text.includes('function') ||
      m.text.includes('interface') ||
      m.text.includes('class') ||
      m.text.includes('//') && (m.text.includes('persist') || m.text.includes('match') || m.text.includes('replay') || m.text.includes('function_try'))
    );
  return relevant.map(m => ({ file: m.file, line: m.line, text: m.text.trim() }));
}

function findMemoryTsExportsAndComments(): { file: string; line: number; text: string }[] {
  // Search for export statements and comments in src/memory.ts
  const matches = searchText('src/memory.ts');
  const relevant = matches
    .filter(m => m.file === 'src/memory.ts')
    .filter(m => m.text.includes('export') || m.text.includes('//'));
  return relevant.map(m => ({ file: m.file, line: m.line, text: m.text.trim() }));
}

function findMemoryTsKeyTerms(): { file: string; line: number; text: string }[] {
  // Search for key terms in src/memory.ts
  const matches = searchText('src/memory.ts');
  const relevant = matches
    .filter(m => m.file === 'src/memory.ts')
    .filter(m => 
      m.text.includes('export') ||
      m.text.includes('function') ||
      m.text.includes('interface') ||
      m.text.includes('class') ||
      (m.text.includes('//') && 
       (m.text.toLowerCase().includes('persist') ||
        m.text.toLowerCase().includes('match') ||
        m.text.toLowerCase().includes('replay') ||
        m.text.toLowerCase().includes('function_try')))
    );
  return relevant.map(m => ({ file: m.file, line: m.line, text: m.text.trim() }));
}

function findMemoryTsLines(): { file: string; line: number; text: string }[] {
